// Exercises the real UI with a local manager and fixture CLI only.
const {chromium}=require('playwright');
const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({headless:true,channel:process.env.TEAMX_BROWSER_CHANNEL || undefined});
 try{
  const page=await browser.newPage({viewport:{width:1440,height:1000}}),errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.goto(process.argv[2]);
  await page.locator('.member-summary').first().click();
  await page.locator('#agent-tab-platforms').click();
  await page.getByRole('button',{name:'编辑 飞书 的通知设置',exact:true}).click();
  await page.waitForFunction(()=>document.getElementById('lark-private-enabled').checked && !document.getElementById('lark-fields').disabled);
  assert.equal(await page.locator('#lark-private-enabled').isChecked(),true);
  assert.equal(await page.locator('#lark-groups-enabled').isChecked(),false);
  assert.equal(await page.locator('#lark-scope').isChecked(),true);
  const heading=page.locator('#lark-private-settings > summary');
  await page.locator('#lark-private-title').click();
  await page.locator('#lark-private-enabled').uncheck();
  assert.equal(await page.locator('#lark-private-settings').evaluate(el=>el.open),true);
  await page.locator('#lark-private-enabled').check();
  await heading.focus();await page.keyboard.press('Enter');
  assert.equal(await page.locator('#lark-private-settings').evaluate(el=>el.open),false);
  assert.equal(await page.locator('#lark-private-enabled').isChecked(),true);
  await heading.focus();await page.keyboard.press('Space');
  await page.locator('#lark-scope').uncheck();
  await page.locator('#lark-private-chat-picker-summary').click();
  await page.locator('#lark-private-chat-options input[value="oc_private"]').check();
  assert.equal(await page.locator('#lark-private-chat-options input[value="oc_group"]').count(),0);
  await page.locator('#lark-scope').check();
  assert.equal(await page.locator('#lark-private-chat-selection').isVisible(),false);
  await page.locator('#lark-save').click();await page.locator('#lark-feedback').filter({hasText:'设置已保存'}).waitFor();
  await page.locator('#notification-detail').screenshot({path:'/tmp/teamx-lark-scope-all-desktop.png'});
  await page.setViewportSize({width:390,height:844});
  await page.locator('#lark-scope').uncheck();
  await page.locator('#lark-private-chat-picker-summary').click();
  assert.equal(await page.locator('#lark-private-chat-selected button').count(),1);
  await page.locator('#lark-groups-title').click();
  assert.equal(await page.locator('#lark-groups-enabled').isChecked(),false);
  await page.locator('#lark-groups-chat-picker-summary').click();
  await page.locator('#lark-groups-chat-options input[value="oc_group"]').waitFor();
  assert.equal(await page.locator('#lark-groups-chat-options input[value="oc_private"]').count(),0);
  assert.equal(await page.locator('#notification-detail').evaluate(el=>el.scrollWidth>el.clientWidth+1),false);
  await page.locator('#notification-detail').screenshot({path:'/tmp/teamx-lark-scope-specified-mobile.png'});
  await page.locator('#lark-save').click();await page.locator('#lark-feedback').filter({hasText:'设置已保存'}).waitFor();
  assert.equal(await page.locator('#lark-private-chat-selected button').count(),1);
  assert.deepEqual(errors,[]);
  console.log(JSON.stringify({fixture_only:true,separate_categories:true,checkbox_disclosure_independent:true,restore_after_save:true,mobile_overflow:false,page_errors:0}));
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
